//! Sky models from the PyGDSM GSM2016 model, generated by `scripts/gsm_sky.py`.

use std::time::Duration;

use serde::{Deserialize, Serialize};
use tokio::process::Command;

/// The generator script, embedded so the binary does not depend on its working directory.
const SCRIPT: &str = include_str!("../scripts/gsm_sky.py");

/// First use may download the GSM2016 component data (~hundreds of MB), so be generous.
const TIMEOUT: Duration = Duration::from_secs(15 * 60);

#[derive(Deserialize)]
#[serde(rename_all = "kebab-case")]
pub enum Frame {
    /// Local east/north/up frame on the lunar far-side equator at `epoch`.
    LunarFarside,
    Equatorial,
    Galactic,
}

#[derive(Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum Resolution {
    Auto,
    Low,
    Hi,
}

#[derive(Deserialize)]
pub struct GsmRequest {
    pub nside: u32,
    pub maps: u32,
    /// Highest order of the log-polynomial spectrum fitted per pixel (1 = power law, at most 3).
    #[serde(default = "default_order")]
    pub order: u32,
    /// Map frequency range in Hz.
    pub fmin: f64,
    pub fmax: f64,
    pub frame: Frame,
    /// UTC epoch (ISO 8601) for the lunar far-side frame.
    pub epoch: Option<String>,
    pub resolution: Resolution,
    pub above_horizon: bool,
}

fn default_order() -> u32 {
    3
}

#[derive(Serialize)]
pub struct GsmResponse {
    /// Sky model in fringe's sources CSV format.
    pub csv: String,
    pub summary: serde_json::Value,
}

impl GsmRequest {
    fn validate(&self) -> Result<(), String> {
        if !self.nside.is_power_of_two() || self.nside > 1024 {
            return Err("NSIDE must be a power of two between 1 and 1024".into());
        }
        if !(2..=256).contains(&self.maps) {
            return Err("the number of maps must be between 2 and 256".into());
        }
        if !(1..=3).contains(&self.order) {
            return Err("the spectral order must be 1, 2 or 3".into());
        }
        if !(self.fmin.is_finite() && self.fmin >= 10e6) {
            return Err("GSM2016 is only defined above 10 MHz".into());
        }
        if !(self.fmax.is_finite() && self.fmax > self.fmin && self.fmax <= 5e12) {
            return Err("the maximum map frequency must exceed the minimum (and be at most 5 THz)".into());
        }
        if let Some(epoch) = &self.epoch
            && (epoch.len() > 40 || !epoch.chars().all(|c| c.is_ascii_alphanumeric() || "-:.".contains(c)))
        {
            return Err("the epoch must be an ISO 8601 UTC time such as 2026-01-01T00:00:00".into());
        }
        Ok(())
    }
}

/// Checks (without importing pygdsm, which triggers data downloads) that the generator's
/// Python dependencies are installed.
pub async fn available(python: &str) -> bool {
    Command::new(python)
        .args([
            "-c",
            "import importlib.util, sys; \
             sys.exit(0 if all(importlib.util.find_spec(m) for m in ('pygdsm', 'healpy', 'astropy', 'numpy')) else 1)",
        ])
        .output()
        .await
        .map(|o| o.status.success())
        .unwrap_or(false)
}

pub async fn generate(python: &str, req: GsmRequest) -> Result<GsmResponse, String> {
    req.validate()?;

    let mut cmd = Command::new(python);
    cmd.arg("-c")
        .arg(SCRIPT)
        .args(["--nside", &req.nside.to_string()])
        .args(["--maps", &req.maps.to_string()])
        .args(["--order", &req.order.to_string()])
        .args(["--fmin", &req.fmin.to_string()])
        .args(["--fmax", &req.fmax.to_string()])
        .args([
            "--frame",
            match req.frame {
                Frame::LunarFarside => "lunar-farside",
                Frame::Equatorial => "equatorial",
                Frame::Galactic => "galactic",
            },
        ])
        .args([
            "--resolution",
            match req.resolution {
                Resolution::Auto => "auto",
                Resolution::Low => "low",
                Resolution::Hi => "hi",
            },
        ])
        .kill_on_drop(true);
    if !req.above_horizon {
        cmd.arg("--all-sky");
    }
    if let Some(epoch) = &req.epoch {
        cmd.args(["--epoch", epoch]);
    }

    let output = tokio::time::timeout(TIMEOUT, cmd.output())
        .await
        .map_err(|_| "GSM generation timed out".to_string())?
        .map_err(|e| format!("failed to run {python}: {e}"))?;

    let stderr = String::from_utf8_lossy(&output.stderr);
    if !output.status.success() {
        let tail: Vec<&str> = stderr.lines().rev().take(6).collect();
        let tail: Vec<&str> = tail.into_iter().rev().collect();
        return Err(format!("GSM generation failed: {}", tail.join("\n")));
    }

    let summary = stderr
        .lines()
        .rev()
        .find_map(|l| l.strip_prefix("SUMMARY "))
        .and_then(|s| serde_json::from_str(s).ok())
        .unwrap_or(serde_json::Value::Null);

    Ok(GsmResponse {
        csv: String::from_utf8(output.stdout).map_err(|e| e.to_string())?,
        summary,
    })
}
